        assert_eq!(eval("let f = x: x; in f (1 + 2)").as_int(), Ok(3));
        assert_eq!(eval("let f = x: 7; in f (1 / 0)").as_int(), Ok(7));
        assert_eq!(eval("let x = 1; f = y: x + y; in f 2").as_int(), Ok(3));
