    #[test]
    fn derivation_strict_structured_attrs_requires_string_special_attrs() {
        for source in [
            r#"derivationStrict {
                 name = "foo";
                 system = ":";
                 builder = 1;
                 __structuredAttrs = true;
               }"#,
            r#"derivationStrict {
                 name = "foo";
                 system = 1;
                 builder = ":";
                 __structuredAttrs = true;
               }"#,
            r#"derivationStrict {
                 name = "foo";
                 system = ":";
                 builder = ":";
                 __structuredAttrs = true;
                 outputHash = "";
                 outputHashAlgo = true;
               }"#,
            r#"derivationStrict {
                 name = "foo";
                 system = ":";
                 builder = ":";
                 __structuredAttrs = true;
                 outputs = [ 1 ];
               }"#,
        ] {
            let error = eval_whnf_owned(&lower(source))
                .expect_err("structured special attr must be a string");
            assert!(
                matches!(
                    error.kind(),
                    TreeWalkErrorKind::Type {
                        expected: "string",
                        ..
                    }
                ),
                "{source}: {error:?}"
            );
        }

        for source in [
            r#"derivationStrict {
                 name = "foo";
                 system = builtins.appendContext ":" {
                   "/nix/store/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa-src" = { path = true; };
                 };
                 builder = ":";
                 __structuredAttrs = true;
               }"#,
            r#"derivationStrict {
                 name = "foo";
                 system = ":";
                 builder = ":";
                 __structuredAttrs = true;
                 outputHash = "";
                 outputHashAlgo = builtins.appendContext "sha256" {
                   "/nix/store/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa-src" = { path = true; };
                 };
               }"#,
            r#"derivationStrict {
                 name = "foo";
                 system = ":";
                 builder = ":";
                 __structuredAttrs = true;
                 outputs = [
                   (builtins.appendContext "out" {
                     "/nix/store/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa-src" = { path = true; };
                   })
                 ];
               }"#,
        ] {
            let error = eval_whnf_owned(&lower(source))
                .expect_err("structured special attr must not carry context");
            assert!(
                matches!(
                    error.kind(),
                    TreeWalkErrorKind::StringContextNotAllowed {
                        op: "derivationStrict",
                        ..
                    }
                ),
                "{source}: {error:?}"
            );
        }
    }

